// The process, filament and printer settings tabs, generated by
// scripts/build-profiles.mjs from the OrcaSlicer sources the engine is built
// from (PrintConfig.cpp for the option definitions; TabPrint::build,
// TabFilament::build and TabPrinter::build_fff in Tab.cpp for pages and
// groups). See scripts/orca-config.mjs and scripts/orca-tabs.mjs.

export interface OptionDef {
  /** Orca's ConfigOptionType: coFloat, coInt, coBool, coEnum, coPercent, coFloatOrPercent, coString, coStrings, ... */
  type: string
  /** One value per filament/variant (stored as an array). */
  vector: boolean
  label?: string
  full_label?: string
  tooltip?: string
  sidetext?: string
  min?: number
  max?: number
  /** 0 simple, 1 advanced, 2 expert, 3 develop (hidden). Absent means simple. */
  mode?: number
  /** [value, label]; with an *_enum_open gui_type the list is only suggestions. */
  enum?: [string, string][]
  gui_type?: string
  multiline?: boolean
  full_width?: boolean
  readonly?: boolean
  ratio_over?: string
  /** Orca's default in preset form ("0.2", "15%", "1", or an array for vectors). */
  default?: string | string[]
  /** May be "nil" (the filament's retraction overrides: unset means the printer's value). */
  nullable?: boolean
}

export interface OptionLine {
  label?: string
  tooltip?: string
  keys: string[]
  /** Per-option labels the tab sets instead of the definition's (e.g. "Target", "Minimal"). */
  labels?: Record<string, string>
  /** Shown full width (G-code, notes). */
  wide?: boolean
  /** Orca edits this with a custom widget (bed shape, compatible printers, ramming). */
  widget?: boolean
  /** Orca shows an "override" checkbox: unchecked stores "nil". */
  nullable?: boolean
}
export interface OptionGroup { title: string; lines: OptionLine[] }
export interface OptionPage { title: string; groups: OptionGroup[] }
/** A settings tab: pages, groups and option definitions. */
export interface SettingsSchema { pages: OptionPage[]; options: Record<string, OptionDef> }
export type ProcessSchema = SettingsSchema

export const MODES = [['Simple', 0], ['Advanced', 1], ['Expert', 2]] as const
export type Mode = 0 | 1 | 2

export const visibleIn = (def: OptionDef, mode: Mode) => (def.mode ?? 0) <= mode

/** Integer options picking a filament: 0 is "Default", then one entry per filament slot. */
export const isFilamentPicker = (def: OptionDef) =>
  def.gui_type === 'i_enum_open' && !def.enum && def.type === 'coInt'
